const createSchema = () => ({ parse: (value: unknown) => value });
export const GraphStateSchema = createSchema();
export const GraphInputSchema = createSchema();
export const GraphOutputSchema = createSchema();

import { END, START, StateGraph } from '@langchain/langgraph';
import { GraphInputSchema, GraphOutputSchema, GraphStateSchema } from './contracts.js';
const prepare = async (state: unknown) => state;
const respond = async (state: unknown) => state;
const route = () => 'done';
const builder = new StateGraph({ state: GraphStateSchema, input: GraphInputSchema, output: GraphOutputSchema });
builder.addNode('prepare', prepare);
builder.addNode('respond', respond, { timeout: 1000 });
builder.addEdge(START, 'prepare');
builder.addEdge('prepare', 'respond');
builder.addConditionalEdges('respond', route, { done: END });
export const supportGraph = builder.compile({ name: 'support_graph' });

import { entrypoint, getPreviousState, interrupt, task } from '@langchain/langgraph';
const prepare = task('prepare_task', async (input: unknown) => input);
export const supportWorkflow = entrypoint({ name: 'support_workflow' }, async (input: unknown) => {
  const prepared = await prepare(input);
  interrupt({ prepared });
  const previous = getPreviousState<unknown>();
  return entrypoint.final<unknown, unknown>({ value: prepared, save: previous });
});
